nt             max, min;{	int             ch, i = min;	mvprintw(0, 0, "%s : %02d", s, i);	refresh();	while ((ch = getch()) != '\n') {		switch (ch) {		case 'j':			if (i > min)				i--;			break;		case 'k':			if (i < max)				i++;			break;		}		mvprintw(0, 0, "%s : %02d", s, i);		refresh();	}	return i;}void bleed(filed,xof) /*control blocking of stdout (or any fd)*/ int filed,xof;        /*taken from bugs3 */{	int flags;	if ((flags = fcntl(filed, F_GETFL, 0)) < 0)		fatal("fcntl - get flag");	if(xof)    /*if xof is set, don't block filed*/	{		if (fcntl(filed, F_SETFL, flags | FNDELAY) < 0)			fatal("fcntl - set");	}	else       /* block filed */		if (fcntl(0, F_SETFL, flags & ~FNDELAY) < 0)/*block stdin*/			fatal("fcntl - reset");}